UPDATE MANAGER
SET MNGR_DUTY_CD = #{mngrDutyCd}
WHERE USER_NO = #{userNo}

UPDATE MNGR_RQST
SET RQST_DUTY_CD = #{rqstDutyCd},
    RMRK_CN      = #{rmrkCn}
WHERE RQST_NO      = #{rqstNo}
  AND RQST_STTS_CD = 'WAIT'

UPDATE MNGR_RQST
SET RQST_STTS_CD = 'CNL',
    RMRK_CN      = #{rmrkCn}
WHERE RQST_NO      = #{rqstNo}
  AND RQST_STTS_CD = 'WAIT'
